import { exhaustiveCheck } from "@/core/helpers";
import { GiftInformationV1, GiftThemeHost } from "@parksandresorts/webapiproxy-types";

/** Represents a delivery theme with content */
type DeliveryTheme = {
  contentful_id: string;
  title?: string;
  [key: string]: unknown;
};

/** State for giftable product flow */
export type GiftCardState = {
  step: number;
  selectedPriceVariation: number | null;
  customPrice: number | undefined;
  receiverInfo: GiftInformationV1 | null;
  receiverOption: "gift" | "self";
};

/** Actions for gift card state management */
export type GiftCardAction =
  | { type: "SET_STEP"; payload: number }
  | { type: "NEXT_STEP" }
  | { type: "PREVIOUS_STEP" }
  | { type: "SET_PRICE_VARIATION"; payload: number | null }
  | { type: "SET_CUSTOM_PRICE"; payload: number | undefined }
  | { type: "SET_RECEIVER_INFO"; payload: GiftInformationV1 | null }
  | { type: "SET_RECEIVER_OPTION"; payload: "gift" | "self" }
  | {
      type: "SUBMIT_RECEIVER_INFO";
      payload: {
        receiverInfo: GiftInformationV1;
        deliveryThemes?: DeliveryTheme[];
      };
    }
  | { type: "SELECT_VARIATION"; payload: number | null }
  | { type: "SELECT_CUSTOM_PRICE"; payload: number | undefined }
  | { type: "UPDATE_MESSAGE"; payload: string }
  | { type: "UPDATE_THEME"; payload: string }
  | { type: "SELECT_SELF_GIFT" }
  | { type: "INITIALIZE_STATE"; payload?: number };

/** Reducer for gift card state management */
export function giftCardStateReducer(state: GiftCardState, action: GiftCardAction): GiftCardState {
  const type = action.type;
  switch (type) {
    case "SET_STEP":
      return { ...state, step: action.payload };

    case "NEXT_STEP":
      // Move to next step, capped at 3
      return { ...state, step: Math.min(state.step + 1, 3) };

    case "PREVIOUS_STEP":
      // Move to previous step, floored at 1
      return { ...state, step: Math.max(state.step - 1, 1) };

    case "SET_PRICE_VARIATION":
      return { ...state, selectedPriceVariation: action.payload };

    case "SET_CUSTOM_PRICE":
      return { ...state, customPrice: action.payload };

    case "SET_RECEIVER_INFO":
      return { ...state, receiverInfo: action.payload };

    case "SET_RECEIVER_OPTION":
      return { ...state, receiverOption: action.payload };

    case "SUBMIT_RECEIVER_INFO": {
      const { receiverInfo, deliveryThemes } = action.payload;

      // Auto-initialize theme if not set and themes are available
      if (!receiverInfo.theme && deliveryThemes && deliveryThemes.length > 0) {
        receiverInfo.theme = {
          themeHost: GiftThemeHost.CONTENTFUL,
          themeId: deliveryThemes[0].contentful_id,
        };
      }
      return { ...state, receiverInfo };
    }

    case "SELECT_VARIATION":
      // When selecting a variation, clear custom price
      return {
        ...state,
        selectedPriceVariation: action.payload,
        customPrice: undefined,
      };

    case "SELECT_CUSTOM_PRICE":
      // When entering custom price, clear selected variation
      return {
        ...state,
        customPrice: action.payload,
        selectedPriceVariation: null,
      };

    case "UPDATE_MESSAGE": {
      // Update message in receiver info
      if (!state.receiverInfo) return state;
      return {
        ...state,
        receiverInfo: {
          ...state.receiverInfo,
          message: action.payload,
        },
      };
    }

    case "UPDATE_THEME": {
      // Update theme in receiver info
      if (!state.receiverInfo) return state;
      return {
        ...state,
        receiverInfo: {
          ...state.receiverInfo,
          theme: {
            themeHost: GiftThemeHost.CONTENTFUL,
            themeId: action.payload,
          },
        },
      };
    }

    case "SELECT_SELF_GIFT": {
      // Clear receiver info when selecting self-gift
      return {
        ...state,
        receiverInfo: null,
        receiverOption: "self",
      };
    }

    case "INITIALIZE_STATE":
      return createInitialGiftCardState(action.payload);

    default:
      return exhaustiveCheck(type);
  }
}

/**
 * Creates initial state for gift card flow
 */
export function createInitialGiftCardState(firstFixedAmount?: number): GiftCardState {
  return {
    step: 1,
    selectedPriceVariation: firstFixedAmount || null,
    customPrice: undefined,
    receiverInfo: null,
    receiverOption: "gift",
  };
}
