import { Fragment } from "react";
import styles from "./step-visualizer.module.less";
import Icon, { IconName } from "@/core/components/primitives/icon/icon";
import { AnimatePresence, motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";

export type StepVisualizerSummary = {
  icon: IconName;
  /* Optional text to display next to the icon, slightly smaller gap between these and main text
   * Example "x2" */
  iconText?: string;
  text: string;
};

type StepVisualizerProps = {
  headline: string;
  /* Optional headline tag, defaults to h1 */
  headingLevel?: "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  currentStep: number;
  totalSteps: number;
  /* Optional summary of previous steps to display above the headline and visualizer */
  previousStepSummary?: StepVisualizerSummary[];
};

/* Component to visualize steps in a process, with optional summary of previous steps */
export const StepVisualizer = ({
  headline,
  headingLevel = "h1",
  currentStep,
  totalSteps,
  previousStepSummary,
}: StepVisualizerProps) => {
  const HeadingComponent = headingLevel;

  return (
    <div className={styles.wrapper}>
      {/* PREVIOUS STEP SUMMARY */}
      <div className={styles.summaryWrapper}>
        <AnimatePresence mode="sync">
          {previousStepSummary?.map((step) => (
            <motion.div
              className={styles.summaryItemWrapper}
              key={step.text}
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              style={{ overflow: "hidden" }}
              transition={{ duration: 0.3, delay: 0.3, type: "tween", ease: "easeInOut" }}
            >
              <div className={multipleClassNames(styles.summaryItem, "body-m")}>
                <div className={styles.summaryIconWrapper}>
                  <Icon name={step.icon} />
                  {step.iconText && <span>{step.iconText}</span>}
                </div>
                <span>{step.text}</span>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* HEADLINE */}
      <HeadingComponent className={multipleClassNames(styles.headline)}>{headline}</HeadingComponent>

      {/* VISUALIZER */}
      <div className={styles.stepWrapper}>
        {Array.from({ length: totalSteps }, (_, index) => {
          const step = index + 1;
          const isLastStep = step === totalSteps;
          const stepStatus = step === currentStep ? "active" : step < currentStep ? "complete" : "inactive";

          return (
            <Fragment key={step}>
              <AnimatePresence mode="wait" initial={false}>
                <motion.div
                  animate={stepStatus}
                  className={styles.step}
                  layout="size"
                  key={`step-${step}`}
                  initial={false}
                  transition={{
                    duration: 0.3,
                    type: "tween",
                    ease: "circOut",
                  }}
                  data-status={stepStatus}
                >
                  {stepStatus === "complete" ? <Icon name="done" /> : <span>{step}</span>}
                </motion.div>
              </AnimatePresence>
              {!isLastStep && <span className={styles.divider}></span>}
            </Fragment>
          );
        })}
      </div>
    </div>
  );
};
