import { AnimatePresence, motion } from "framer-motion";
import RadioButtons from "@/core/components/primitives/radio-buttons/radio-buttons";
import TextArea from "@/core/components/primitives/text-area/text-area";
import { getStyleOverrides } from "@/core/components/primitives/text-block/text-block";
import { useTranslation } from "react-i18next";
import styles from "./customization-step.module.less";
import { TextBlockWithContentfulNaming, GiftCardDispatch, StepPropsWithThemes } from "../../types";
import { isNonEmptyArray, multipleClassNames } from "@/core/helpers";
import { PrimaryButton, SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";

const MESSAGE_MAX_LENGTH = 200;

const ThemesRadioButtons = ({
  textBlock,
  isSelected,
}: {
  textBlock: TextBlockWithContentfulNaming;
  isSelected: boolean;
}) => {
  const { t } = useTranslation();
  const { contentful_id, title, text, componentTheme, customColors } = textBlock;
  const themeDescription = text?.childMarkdownRemark?.excerpt;

  return (
    <div>
      <AnimatePresence initial={false}>
        <motion.div
          key={contentful_id + "-wrapper"}
          initial={{ scale: 1 }}
          animate={{ scale: isSelected ? 1.05 : 1 }}
          exit={{ scale: 1 }}
          transition={{ type: "tween", ease: "easeOut", duration: 0.1 }}
          data-is-selected={isSelected}
          className={multipleClassNames(
            styles.themeRadioButtonLabelWrapper,
            componentTheme &&
              `component-theme component-theme-${componentTheme.toLowerCase()} ${componentTheme.toLowerCase()}`,
            !componentTheme && styles.defaultTheme,
          )}
          style={getStyleOverrides(customColors)}
        >
          {isSelected && (
            <motion.div
              key={contentful_id + "-selected"}
              initial={{ opacity: 0, scale: 0.5, y: "var(--foundation-spacing-x1)", x: "var(--foundation-spacing-x1)" }}
              animate={{ opacity: 1, scale: 1, y: 0, x: 0 }}
              exit={{ opacity: 0, y: "var(--foundation-spacing-x1)", x: "var(--foundation-spacing-x1)" }}
              transition={{ type: "tween", ease: "easeOut" }}
              className={styles.themeRadioButtonSelectedWrapper}
            >
              <span className={multipleClassNames(styles.themeRadioButtonSelectedLabel, "body-xxs")}>
                {t("giftableProductBlockCustomizationStepChosenThemeLabel")}
              </span>
            </motion.div>
          )}
          <span className={multipleClassNames(styles.themeRadioButtonLabel, "body-m", "bold")}>{title}</span>
          {themeDescription && (
            <span className={multipleClassNames(styles.themeRadioButtonLabelDescription, "body-xxs")}>
              {themeDescription}
            </span>
          )}
        </motion.div>
      </AnimatePresence>
    </div>
  );
};

type BottomButtonsProps = {
  dispatch: GiftCardDispatch;
  onAddToCart: () => void;
  isAddingToCart: boolean;
};
const BottomButtons = ({ dispatch, onAddToCart, isAddingToCart }: BottomButtonsProps) => {
  const { t } = useTranslation();
  return (
    <div className={styles.bottomButtons}>
      <SecondaryButton
        label={t("back")}
        isFullWidth
        complementary
        onClick={() => dispatch({ type: "PREVIOUS_STEP" })}
      />
      <PrimaryButton
        label={isAddingToCart ? t("addingToCart") : t("addToCart")}
        isFullWidth
        onClick={onAddToCart}
        isDisabled={isAddingToCart}
      />
    </div>
  );
};

type CustomizationStepProps = StepPropsWithThemes & {
  onAddToCart: () => void;
  isAddingToCart: boolean;
};
const CustomizationStep = ({
  deliveryThemes,
  state,
  dispatch,
  onAddToCart,
  isAddingToCart,
}: CustomizationStepProps) => {
  const { t } = useTranslation();
  const receiverInfo = state.receiverInfo;

  const handleMessageChange = (message: string) => {
    dispatch({
      type: "UPDATE_MESSAGE",
      payload: message,
    });
  };

  const handleThemeChange = (themeId: string) => {
    dispatch({
      type: "UPDATE_THEME",
      payload: themeId,
    });
  };

  // Helper to get the current selected theme ID
  const getSelectedThemeId = () => {
    return receiverInfo?.theme?.themeId || deliveryThemes?.[0]?.contentful_id || null;
  };

  const selectedThemeId = getSelectedThemeId();

  return (
    <div className={styles.customizationsWrapper}>
      {receiverInfo ? (
        <>
          <TextArea
            label={t("giftableProductBlockCustomizationStepGreetingLabel")}
            value={receiverInfo?.message || ""}
            name="giftGreeting"
            id="giftGreeting"
            inputClassName={styles.greetingTextArea}
            maxLength={MESSAGE_MAX_LENGTH}
            onChange={(_: string, value: string) => handleMessageChange(value)}
          />
          {isNonEmptyArray(deliveryThemes) && (
            <AnimatePresence>
              <RadioButtons
                name="themeSelection"
                label={t("giftableProductBlockCustomizationStepThemeLabel")}
                options={deliveryThemes.map((textBlock) => ({
                  label: (
                    <ThemesRadioButtons
                      textBlock={textBlock}
                      isSelected={selectedThemeId === textBlock.contentful_id}
                    />
                  ),
                  value: textBlock.contentful_id,
                }))}
                value={selectedThemeId || deliveryThemes[0].contentful_id}
                radioItemsWrapperClassName={styles.themesRadioButtonsWrapper}
                radioItemClassName={styles.themesRadioButton}
                onChange={(_: string, value: string) => handleThemeChange(value)}
              />
            </AnimatePresence>
          )}
        </>
      ) : (
        <div className={styles.noReceiverInfo}>
          <p className="bold">{t("giftableProductBlockCustomizationStepNoReceiverInfoHeading")}</p>
          <p>{t("giftableProductBlockCustomizationStepNoReceiverInfoParagraph")}</p>
        </div>
      )}
      <BottomButtons dispatch={dispatch} onAddToCart={onAddToCart} isAddingToCart={isAddingToCart} />
    </div>
  );
};

export default CustomizationStep;
