const createMockGiftCardProduct = (
  overrides: Partial<ProductInformationResponseItem> = {},
): ProductInformationResponseItem => {
  const base: Partial<ProductInformationResponseItem> = {
    id: 67890,
    friendlySalesNameSwe: "Digital Gift Card",
    friendlySalesNameEng: "Digital Gift Card",
    priceIncludingVat: 500,
    priceExcludingVat: 500,
    ordinaryPrice: undefined,
    stockLevel: 100,
    minimumQuantity: 1,
    deliveryTypes: [{ deliveryType: DeliveryType.DIGITAL }],
    metadata: {
      bookingLastActivityRelativeTime: undefined,
      giftCardSettings: {
        giftCardFixedAmounts: [250, 500, 750, 1000],
        minGiftCardOptionalAmount: 100,
        maxGiftCardOptionalAmount: 5000,
      },
    },
  };

  return { ...base, ...overrides } as ProductInformationResponseItem;
};

