import { useEffect, useState } from "react";
import InputField from "@/core/components/primitives/input-field/input-field";
import InputHelperText from "@/core/components/primitives/input-helper-text/input-helper-text";
import PhoneOrEmailFields from "@/core/components/primitives/phone-or-email-fields/phone-or-email-fields";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import { SecondaryButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import CheckboxButtons from "@/core/components/primitives/checkbox-buttons/checkbox-buttons";
import { DigitalDeliveryTypeV1, GiftInformationV1 } from "@parksandresorts/webapiproxy-types";
import { useTranslation } from "react-i18next";
import { AnimatePresence, motion } from "framer-motion";
import { useForm, buildField, DateHelper, createDate } from "@/core/helpers";
import { StepPropsWithThemes } from "@/core/components/blocks/giftable-product-block/types";
import {
  MethodType,
  createContactField,
} from "@/core/components/primitives/phone-or-email-fields/phone-or-email-fields";
import styles from "./receiver-step.module.less";

const MAX_TIME = "23:59";
const DEFAULT_TIME = "12:00";

type ReceiverOption = "gift" | "self";
type ScheduledDeliveryState = "closed" | "open";

const convertDeliveryTypeToMethod = (deliveryType?: DigitalDeliveryTypeV1): MethodType => {
  return deliveryType === DigitalDeliveryTypeV1.SMS ? "phone" : "email";
};

const convertMethodToDeliveryType = (method: MethodType): DigitalDeliveryTypeV1 => {
  return method === "phone" ? DigitalDeliveryTypeV1.SMS : DigitalDeliveryTypeV1.EMAIL;
};

const getDateBounds = (maximumScheduleWeeks: number) => {
  const today = createDate();
  const maxDate = DateHelper.addDays(today, 7 * maximumScheduleWeeks);
  return {
    minDateString: DateHelper.toStringYYYYMMDD(today),
    maxDateString: DateHelper.toStringYYYYMMDD(maxDate),
  };
};

const getConstrainedDate = (date: string, minDate: string, maxDate: string): string => {
  if (date < minDate) return minDate;
  if (date > maxDate) return maxDate;
  return date;
};

const getMinTime = (date: string): string => {
  return DateHelper.isToday(date) ? DateHelper.toStringTimeHHMM(DateHelper.addMinutes(createDate(), 15)) : "00:00";
};

const expandTransition = {
  enter: { duration: 0.2, type: "spring", stiffness: 300, damping: 15, mass: 1.2 },
  exit: { duration: 0.2, ease: "easeOut", type: "tween" },
} as const;

type ReceiverStepProps = StepPropsWithThemes & {
  maximumScheduleWeeks: number;
};
const ReceiverStep = ({ state, dispatch, deliveryThemes, maximumScheduleWeeks }: ReceiverStepProps) => {
  const { t } = useTranslation();

  // Date boundaries for scheduled delivery
  const { minDateString, maxDateString } = getDateBounds(maximumScheduleWeeks);

  const { receiverInfo, receiverOption } = state;

  // Create contact form for phone/email fields
  const phoneFieldName = "deliverToPhone";
  const emailFieldName = "deliverToEmail";
  const phoneField = createContactField({
    fieldType: "phone",
    name: phoneFieldName,
    label: "giftableProductBlockReceiverMethodPhone",
    value: receiverInfo?.deliveryType === DigitalDeliveryTypeV1.SMS ? receiverInfo.deliverTo : "",
    t,
  }).field;
  const emailField = createContactField({
    fieldType: "email",
    name: emailFieldName,
    label: "giftableProductBlockReceiverMethodEmail",
    value: receiverInfo?.deliveryType === DigitalDeliveryTypeV1.EMAIL ? receiverInfo.deliverTo : "",
    t,
  }).field;
  const [contactForm, , handleContactChange, , validateContactForm, , focusOnContactField] = useForm(
    {
      fields: new Map<string, typeof phoneField>().set(phoneField.name, phoneField).set(emailField.name, emailField),
    },
    true,
  );

  const [selectedDeliveryOption, setSelectedDeliveryOption] = useState<MethodType>(
    convertDeliveryTypeToMethod(receiverInfo?.deliveryType),
  );

  const [scheduledDeliveryState, setScheduledDeliveryState] = useState<ScheduledDeliveryState>(
    receiverInfo?.scheduledDelivery?.deliveryDate ? "open" : "closed",
  );

  const [scheduleForm, , handleScheduleFieldChange, , validateScheduleForm, , focusOnScheduleField] = useForm(
    {
      fields: new Map()
        .set(
          "scheduledDate",
          buildField("scheduledDate", {
            value: receiverInfo?.scheduledDelivery?.deliveryDate ?? minDateString,
            isRequired: true,
            label: t("date"),
            type: "INPUT_FIELD",
          }),
        )
        .set(
          "scheduledTime",
          buildField("scheduledTime", {
            value: receiverInfo?.scheduledDelivery?.deliveryTime ?? DEFAULT_TIME,
            isRequired: true,
            label: t("time"),
            type: "INPUT_FIELD",
          }),
        ),
    },
    true,
  );

  const scheduledDate = scheduleForm.fields.get("scheduledDate")?.value as string;
  const scheduledTime = scheduleForm.fields.get("scheduledTime")?.value as string;
  const constrainedDate = getConstrainedDate(scheduledDate || minDateString, minDateString, maxDateString);
  const minTime = getMinTime(constrainedDate);

  const receiverOptions = [
    { label: t("giftableProductBlockReceiverOptionGift"), value: "gift" as const },
    { label: t("giftableProductBlockReceiverOptionSelf"), value: "self" as const },
  ];

  // Auto-correct date if it goes out of bounds
  useEffect(() => {
    if (scheduledDate !== constrainedDate) {
      handleScheduleFieldChange("scheduledDate", constrainedDate);
    }
  }, [scheduledDate, constrainedDate, handleScheduleFieldChange]);

  // Auto-correct time if it's in the past for today
  useEffect(() => {
    if (scheduledDate && scheduledTime && DateHelper.isToday(scheduledDate) && scheduledTime < minTime) {
      handleScheduleFieldChange("scheduledTime", minTime);
    }
  }, [scheduledDate, scheduledTime, minTime, handleScheduleFieldChange]);

  const handleReceiverOptionChange = (_: string, value: string) => {
    dispatch({ type: "SET_RECEIVER_OPTION", payload: value as ReceiverOption });
  };

  const handleNextClick = () => {
    // Self-gift: skip receiver details
    if (receiverOption === "self") {
      dispatch({ type: "SELECT_SELF_GIFT" });
      dispatch({ type: "NEXT_STEP" });
      return;
    }

    // Validate contact (email/phone)
    const { isFormValid } = validateContactForm();
    if (!isFormValid) {
      focusOnContactField("FIRST_INVALID");
      return;
    }

    // Validate scheduled delivery if enabled
    if (scheduledDeliveryState === "open") {
      const { isFormValid: isScheduleValid } = validateScheduleForm();
      if (!isScheduleValid) {
        focusOnScheduleField("FIRST_INVALID");
        return;
      }
    }

    // Get the contact value from the form
    const deliverTo =
      selectedDeliveryOption === "phone"
        ? contactForm.fields.get(phoneFieldName)?.value
        : contactForm.fields.get(emailFieldName)?.value;
    if (!deliverTo) return;

    // Build and submit receiver info
    const receiverInfoPayload: GiftInformationV1 = {
      ...receiverInfo,
      deliverTo,
      deliveryType: convertMethodToDeliveryType(selectedDeliveryOption),
      scheduledDelivery:
        scheduledDeliveryState === "open" ? { deliveryDate: scheduledDate, deliveryTime: scheduledTime } : undefined,
    };

    dispatch({ type: "SUBMIT_RECEIVER_INFO", payload: { receiverInfo: receiverInfoPayload, deliveryThemes } });
    dispatch({ type: "NEXT_STEP" });
  };

  return (
    <div className={styles.receiverWrapper}>
      <div className={styles.receiverContent}>
        <StyledRadioButtons
          name="receiverOption"
          key="receiverOption"
          options={receiverOptions}
          value={receiverOption}
          onChange={handleReceiverOptionChange}
        />

        <AnimatePresence mode="wait" initial={false}>
          {receiverOption === "gift" && (
            <motion.div
              key="gift"
              initial={{ opacity: 0.2, x: "-100%" }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0.2, x: "-100%" }}
              transition={{ type: "tween", duration: 0.2 }}
              className={styles.receiverGiftWrapper}
            >
              <div className={styles.receiverDetails}>
                <PhoneOrEmailFields
                  form={contactForm}
                  method={selectedDeliveryOption}
                  radioGroupName="deliveryMethod"
                  radioGroupLabel="giftableProductBlockReceiverMethodHeading"
                  phoneFieldName={phoneFieldName}
                  emailFieldName={emailFieldName}
                  reverseOptions
                  onMethodChange={(_, method) => setSelectedDeliveryOption(method)}
                  onContactChange={(name, value) => handleContactChange(name, value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") handleNextClick();
                  }}
                />
              </div>

              <div className={styles.scheduledDeliveryWrapper}>
                <CheckboxButtons
                  name="scheduledDelivery"
                  variant="small"
                  options={[{ value: "enabled", label: t("giftableProductBlockReceiverScheduleDeliveryCheckbox") }]}
                  value={scheduledDeliveryState === "open" ? "enabled" : ""}
                  legend={t("giftableProductBlockReceiverScheduleDeliveryLabel")}
                  legendClassName={styles.scheduledDeliveryTopLabel}
                  checkboxClassName={styles.scheduledDeliveryCheckbox}
                  onChange={(_, value) => setScheduledDeliveryState(value.includes("enabled") ? "open" : "closed")}
                />

                <AnimatePresence mode="sync" initial={false}>
                  {scheduledDeliveryState === "open" && (
                    <motion.div
                      layout
                      initial={{ height: 0 }}
                      animate={{ height: "auto", transition: expandTransition.enter }}
                      exit={{ height: 0, transition: expandTransition.exit }}
                      className={styles.scheduledDeliveryDetails}
                    >
                      <div className={styles.scheduledDeliveryInputs}>
                        <InputField
                          type="date"
                          formField={scheduleForm.fields.get("scheduledDate")}
                          min={minDateString}
                          max={maxDateString}
                          onChange={handleScheduleFieldChange}
                        />
                        <InputField
                          type="time"
                          formField={scheduleForm.fields.get("scheduledTime")}
                          min={minTime}
                          max={MAX_TIME}
                          onChange={handleScheduleFieldChange}
                        />
                      </div>
                      <InputHelperText
                        helperText={t("giftableProductBlockReceiverScheduleDeliveryHelperText", {
                          weeks: maximumScheduleWeeks,
                        })}
                        contentfulLabelId="giftableProductBlockReceiverScheduleDeliveryHelperText"
                      />
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            </motion.div>
          )}

          {receiverOption === "self" && (
            <motion.div
              key="self"
              initial={{ opacity: 0.2, x: "100%" }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0.2, x: "100%" }}
              transition={{ type: "tween", duration: 0.2 }}
              className={styles.receiverSelfWrapper}
            >
              <p data-contentful-label-id="giftableProductBlockReceiverSelfMessage">
                {t("giftableProductBlockReceiverSelfMessage")}
              </p>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <div className={styles.bottomButtons}>
        <SecondaryButton
          label={t("back")}
          isFullWidth
          complementary
          onClick={() => dispatch({ type: "PREVIOUS_STEP" })}
        />
        <PrimaryButton label={t("next")} isFullWidth onClick={handleNextClick} />
      </div>
    </div>
  );
};

export default ReceiverStep;
