import { useReducer, useCallback, Dispatch } from "react";
import { DeliveryType } from "@parksandresorts/webapiproxy-types";
import { useProductBlockCartOperations } from "@/core/hooks/use-product-block-cart-operations";
import { useShopServiceCartContext } from "@/core/contexts";
import { useProductTracking } from "@/core/hooks/use-product-tracking";
import { useEffectivePrice } from "@/core/hooks/use-effective-price";
import { useIsMobile } from "@/core/hooks/use-is-mobile";
import { createCartItem } from "@/core/helpers/cart-item-builder";
import {
  giftCardStateReducer,
  createInitialGiftCardState,
  GiftCardState,
  GiftCardAction,
} from "@/core/state/gift-card/gift-card-state-reducer";
import { ContextValues } from "@/core/components/blocks/giftable-product-block/types";
import { GlkBackedProduct } from "./product-hooks";
import { getPrimaryDeliveryType } from "../helpers/product-helper";

type UseGiftCardStateReturn = {
  state: GiftCardState;
  dispatch: Dispatch<GiftCardAction>;
  deliveryType: DeliveryType;
  addToCart: () => Promise<void>;
  isAddingToCart: boolean;
};

export const useGiftCardState = (
  product: GlkBackedProduct,
  setContextValues?: (values: ContextValues) => void,
): UseGiftCardStateReturn => {
  const isMobileView = useIsMobile();

  // Use shared product tracking
  useProductTracking(product);

  // Initialize state with reducer
  const firstFixedAmount = product.glkProduct.metadata?.giftCardSettings?.giftCardFixedAmounts?.[0];
  const [state, dispatch] = useReducer(giftCardStateReducer, createInitialGiftCardState(firstFixedAmount));

  // Use shared cart operations with gift card specific success handling
  const { addToCartWithErrorHandling } = useProductBlockCartOperations({
    product,
    successActions: {
      showCart: setContextValues
        ? () => setContextValues({ showCart: true, showMenu: false, showSearch: false })
        : undefined,
      showCartNotification: isMobileView,
      cleanState: () => {
        dispatch({ type: "INITIALIZE_STATE", payload: firstFixedAmount });
      },
    },
  });

  // Get loading state directly from context instead of from useProductBlockCartOperations
  const { isLoading } = useShopServiceCartContext();

  const deliveryType = getPrimaryDeliveryType(product, DeliveryType.DIGITAL);

  // Use shared hook for price calculation
  const { effectivePrice, isVariablePrice } = useEffectivePrice(
    product,
    state.selectedPriceVariation,
    state.customPrice,
  );

  const addToCart = useCallback(async () => {
    const cartItem = createCartItem(product, {
      receiverInfo: state.receiverInfo || undefined,
      price: effectivePrice,
      isVariablePrice,
      deliveryType,
      quantity: 1,
    });

    await addToCartWithErrorHandling(cartItem);
  }, [product, state.receiverInfo, effectivePrice, isVariablePrice, deliveryType, addToCartWithErrorHandling]);

  return {
    // State and dispatch
    state,
    dispatch,

    // Product delivery type
    deliveryType,

    // Cart operations
    addToCart,
    isAddingToCart: isLoading,
  };
};
