import styles from "./steps.module.less";
import { StepVisualizer, StepVisualizerSummary } from "@/core/components/primitives/step-visualizer/step-visualizer";
import { CurrencyHelper, DateHelper, getGiftCardSettings } from "@/core/helpers";
import ProductStep from "./product-step/product-step";
import ReceiverStep from "./receiver-step/receiver-step";
import CustomizationStep from "./customization-step/customization-step";
import { GlkBackedProduct, useEffectivePrice, useGiftCardState } from "@/core/hooks";
import { useTranslation } from "react-i18next";
import { motion, AnimatePresence } from "framer-motion";
import animatedScrollTo from "animated-scroll-to";
import { useEffect, useRef } from "react";
import { ContextValues, DeliveryThemeList } from "@/core/components/blocks/giftable-product-block/types";
import { RichTextType } from "@/core/components/primitives/rich-text/rich-text";

type StepsProps = {
  product: GlkBackedProduct;
  deliveryThemes?: DeliveryThemeList;
  description?: RichTextType;
  maximumScheduleWeeks: number;
  setContextValues?: (values: ContextValues) => void;
};
const Steps = ({ product, deliveryThemes, description, maximumScheduleWeeks, setContextValues }: StepsProps) => {
  const { t } = useTranslation();
  const { state, dispatch, addToCart, isAddingToCart } = useGiftCardState(product, setContextValues);
  const { isGiftCardProduct } = getGiftCardSettings(product);
  const { effectivePrice } = useEffectivePrice(product, state.selectedPriceVariation, state.customPrice);
  const stepWrapperRef = useRef<HTMLDivElement>(null);
  const previousStepRef = useRef(state.step);
  const isInitialMount = useRef(true);

  // Determine direction of step change
  const direction = state.step > previousStepRef.current ? 1 : -1;
  previousStepRef.current = state.step;

  // Scroll to top of step area when step changes
  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }
    if (stepWrapperRef.current) {
      const { top } = stepWrapperRef.current.getBoundingClientRect();
      if (top < 0) {
        try {
          animatedScrollTo(stepWrapperRef.current, { verticalOffset: -48, speed: 1350, maxDuration: 500 });
        } catch (error) {
          console.error("Error scrolling to element. Continuing without scrolling.", error);
        }
      }
    }
  }, [state.step]);

  const stepTitles = [
    isGiftCardProduct
      ? t("giftableProductBlockProductStepVariablePriceHeading")
      : t("giftableProductBlockProductStepHeading"),
    t("giftableProductBlockReceiverStepHeading"),
    t("giftableProductBlockCustomizationStepHeading"),
  ];

  const scheduleDeliveryString = state.receiverInfo?.scheduledDelivery?.deliveryDate
    ? t("giftableProductBlockStepSummaryScheduledDeliveryTimed", {
        date: DateHelper.toStringDDMMYYYY(state.receiverInfo?.scheduledDelivery?.deliveryDate),
        time: state.receiverInfo?.scheduledDelivery?.deliveryTime,
      })
    : "";
  const stepSummaries: Array<StepVisualizerSummary> = [
    {
      icon: "check",
      text: t("giftableProductBlockStepSummaryProductAmount", { amount: CurrencyHelper.formatToSek(effectivePrice) }),
    },
    {
      icon: "check",
      text: `${state.receiverInfo?.deliverTo ?? ""} ${scheduleDeliveryString}`,
    },
  ];

  const isSelfGift = !state.receiverInfo?.deliverTo;
  const previousStepSummary =
    state.step > 1
      ? isSelfGift
        ? stepSummaries.slice(0, 1) // Only show first summary for self-gifts
        : stepSummaries.slice(0, state.step - 1)
      : undefined;

  // Animation variants
  const variants = {
    enter: (direction: number) => ({
      x: direction > 0 ? "100%" : "-100%",
      opacity: 0,
    }),
    center: {
      x: 0,
      opacity: 1,
    },
    exit: (direction: number) => ({
      x: direction > 0 ? "-100%" : "100%",
      opacity: 0,
    }),
  };

  const renderStep = () => {
    switch (state.step) {
      case 1:
        return <ProductStep product={product} description={description} state={state} dispatch={dispatch} />;
      case 2:
        return (
          <ReceiverStep
            state={state}
            dispatch={dispatch}
            deliveryThemes={deliveryThemes}
            maximumScheduleWeeks={maximumScheduleWeeks}
          />
        );
      case 3:
        return (
          <CustomizationStep
            deliveryThemes={deliveryThemes}
            state={state}
            dispatch={dispatch}
            onAddToCart={addToCart}
            isAddingToCart={isAddingToCart}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div ref={stepWrapperRef} className={styles.stepWrapper}>
      <StepVisualizer
        headline={stepTitles[state.step - 1] || ""}
        currentStep={state.step}
        totalSteps={3}
        previousStepSummary={previousStepSummary}
      />
      <AnimatePresence initial={false} mode="popLayout" custom={direction}>
        <motion.div
          key={state.step}
          custom={direction}
          variants={variants}
          initial="enter"
          animate="center"
          exit="exit"
          transition={{
            x: { type: "spring", stiffness: 200, damping: 20 },
            opacity: { duration: 0.3 },
          }}
          style={{ width: "100%" }}
        >
          {renderStep()}
        </motion.div>
      </AnimatePresence>
    </div>
  );
};

export default Steps;
