import { useRef } from "react";
import { GiftCardPriceSelector, type GiftCardPriceSelectorRef } from "@/core/components/blocks/product-block/gift-card";
import ProductPrice from "@/core/components/primitives/product-price/product-price";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { getGiftCardSettings, multipleClassNames } from "@/core/helpers";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import styles from "./product-step.module.less";
import { useTranslation } from "react-i18next";
import { BaseStepProps } from "../../types";
import { GlkBackedProduct } from "@/core/hooks";

type ProductStepProps = BaseStepProps & {
  product: GlkBackedProduct;
  description?: RichTextType;
};
const ProductStep = ({ product, description, state, dispatch }: ProductStepProps) => {
  const { t } = useTranslation();
  const priceSelectorRef = useRef<GiftCardPriceSelectorRef>(null);

  const { priceIncludingVat, ordinaryPrice, stockLevel } = product.glkProduct;
  const { customPriceText = null } = product.contentfulProduct ?? {};
  const { hasFixedAmounts, hasCustomPrice, isGiftCardProduct } = getGiftCardSettings(product);

  const productIsInStock = typeof stockLevel !== "number" || stockLevel > 0;
  const bottomButtonLabel = productIsInStock ? t("next") : t("soldOut");

  // Handle next button click with validation
  const handleNext = () => {
    // Validate price selection (validatePrice focuses invalid field internally)
    if (priceSelectorRef.current && !priceSelectorRef.current.validatePrice()) {
      return; // Validation failed
    }

    dispatch({ type: "NEXT_STEP" });
  };

  return (
    <div className={styles.productWrapper}>
      {!hasFixedAmounts && !hasCustomPrice && priceIncludingVat && (
        <div className={styles.price}>
          <ProductPrice
            price={priceIncludingVat}
            previousPrice={ordinaryPrice}
            customPriceText={customPriceText}
            priceClassName={multipleClassNames("heading-s", styles.priceWrapper)}
            ignoreComponentTheme={true}
          />
        </div>
      )}

      {isGiftCardProduct && (
        <GiftCardPriceSelector
          ref={priceSelectorRef}
          product={product}
          selectedPriceVariation={state.selectedPriceVariation}
          setSelectedPriceVariation={(value) => dispatch({ type: "SELECT_VARIATION", payload: value })}
          customPrice={state.customPrice}
          setCustomPrice={(value) => dispatch({ type: "SELECT_CUSTOM_PRICE", payload: value })}
        />
      )}

      <PrimaryButton label={bottomButtonLabel} isFullWidth onClick={handleNext} isDisabled={!productIsInStock} />

      {description && (
        <div className={styles.productDescription}>
          <RichText richText={description} />
        </div>
      )}
    </div>
  );
};

export default ProductStep;
