import structure from "@/core/styling/structure.module.less";
import styles from "./giftable-product-block.module.less";
import ProductBlock from "@/core/components/blocks/product-block/product-block";
import { getPrimaryDeliveryType, multipleClassNames } from "@/core/helpers";
import Steps from "./steps/steps";
import { DeliveryType } from "@parksandresorts/webapiproxy-types";
import { ContextValues, DeliveryThemeList } from "@/core/components/blocks/giftable-product-block/types";
import { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import ImageAndName from "@/core/components/blocks/product-block/components/image-and-name/image-and-name";
import { useProduct } from "@/core/hooks";
import { ProductBlockFragment } from "@/core/types";

export type GiftableProductProps = {
  contentful_id: string;
  productName?: string;
  shortDescriptionInLists?: string;
  giftableProduct: ProductBlockFragment;
  deliveryThemes?: DeliveryThemeList;
  description?: RichTextType;
  maximumScheduleWeeks: number | null;
  isLocked?: boolean;
  isShowingTopBanner?: boolean;
  setContextValues: (values: Partial<ContextValues>) => void;
};

const DEFAULT_MAX_SCHEDULE_WEEKS = 8;

const GiftableProductBlock = ({
  contentful_id: contentfulId,
  productName,
  giftableProduct,
  deliveryThemes,
  description,
  maximumScheduleWeeks,
  setContextValues,
}: GiftableProductProps) => {
  const product = useProduct(Number(giftableProduct.productData?.glkId));

  if (!product) {
    return null;
  }

  const weeks = maximumScheduleWeeks ?? DEFAULT_MAX_SCHEDULE_WEEKS;
  const { productImage, label, componentTheme, backgroundColor } = giftableProduct;
  const productNameToUse = productName || product.name;
  const deliveryType = getPrimaryDeliveryType(product, DeliveryType.DIGITAL);
  const image = productImage?.largeGatsbyImageData ?? productImage?.gatsbyImageData ?? null;

  // Giftable products can only be digital
  if (deliveryType !== DeliveryType.DIGITAL) {
    return <ProductBlock {...giftableProduct} setContextValues={setContextValues} />;
  }

  return (
    <section
      data-contentful-id={contentfulId}
      className={multipleClassNames(
        styles.outerWrapper,
        componentTheme && `component-theme component-theme-${componentTheme} ${componentTheme}`,
      )}
    >
      <div
        className={multipleClassNames(
          structure.blockMaxWidthS,
          styles.innerWrapper,
          backgroundColor && styles.hasBackground,
        )}
      >
        <ImageAndName image={image} productName={productNameToUse} label={label} centerAlignName />
        <Steps
          product={product}
          deliveryThemes={deliveryThemes}
          description={description}
          maximumScheduleWeeks={weeks}
          setContextValues={setContextValues}
        />
      </div>
    </section>
  );
};

export default GiftableProductBlock;
